<script setup>
import {onMounted,ref} from 'vue'
import {getOwnClubStatistics,getOwnClubMatchStatistics} from '../../api/statistics'
const overview=ref({}),records=ref([]),total=ref(0),page=ref(1),loading=ref(false);const money=v=>`￥${Number(v||0).toFixed(2)}`,rate=v=>`${Number(v||0).toFixed(2)}%`
const load=async()=>{loading.value=true;try{const [a,b]=await Promise.all([getOwnClubStatistics(),getOwnClubMatchStatistics({page:page.value,size:10})]);overview.value=a.data;records.value=b.data.records;total.value=b.data.total}finally{loading.value=false}};onMounted(load)
</script>
<template><div v-loading="loading"><h2>本俱乐部主场统计</h2><el-row :gutter="14"><el-col :span="5"><el-card><div>主场比赛</div><b>{{overview.homeMatchCount||0}}</b></el-card></el-col><el-col :span="5"><el-card><div>有效售票</div><b>{{overview.validTicketsSold||0}}</b></el-card></el-col><el-col :span="5"><el-card><div>净销售额</div><b>{{money(overview.netSalesAmount)}}</b></el-card></el-col><el-col :span="4"><el-card><div>平均售票率</div><b>{{rate(overview.averageTicketSaleRate)}}</b></el-card></el-col><el-col :span="5"><el-card><div>平均上座率</div><b>{{rate(overview.averageAttendanceRate)}}</b></el-card></el-col></el-row><el-card class="table"><template #header><b>主场比赛表现</b></template><el-table :data="records"><el-table-column label="比赛" min-width="210"><template #default="{row}">{{row.homeClubName}} vs {{row.awayClubName}}</template></el-table-column><el-table-column prop="matchTime" label="比赛时间" min-width="170"/><el-table-column prop="validSoldCount" label="有效售票"/><el-table-column prop="checkedInCount" label="入场"/><el-table-column label="售票率"><template #default="{row}">{{rate(row.ticketSaleRate)}}</template></el-table-column><el-table-column label="上座率"><template #default="{row}">{{rate(row.attendanceRate)}}</template></el-table-column><el-table-column label="净销售额"><template #default="{row}">{{money(row.netSalesAmount)}}</template></el-table-column></el-table><el-pagination v-if="total>10" v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></el-card></div></template>
<style scoped>.el-card div{color:#6b7280;margin-bottom:10px}.el-card b{font-size:21px}.table{margin-top:18px}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
